/* MMM-GuestWifi
 *
 * Displays a pre-generated QR code for the guest Wi-Fi.
 *
 * Deliberately without a JavaScript library: the code is generated by
 * scripts/make-guest-qr.sh with qrencode as a PNG, and the module only
 * shows the image. That means no QR library version conflict can
 * happen -- there is none.
 *
 * Side effect: escaping of the WIFI string is handled by the shell at
 * generation time, not by JavaScript at runtime. Special characters in
 * the password only need to be handled in exactly one place.
 *
 * ---------------------------------------------------------------------
 * Setup
 * ---------------------------------------------------------------------
 *
 *   ./scripts/make-guest-qr.sh
 *
 * The script reads the SSID and password from config/secrets.js and
 * writes guest-wifi.png into this folder. The PNG file contains the
 * password and is therefore gitignored.
 *
 * Configuration:
 *
 *   {
 *     module: "MMM-GuestWifi",
 *     position: "top_left",
 *     header: "Gast-WLAN",
 *     config: {
 *       ssid: "MeinGastnetz",   // display only, optional
 *       imageSize: 220
 *     }
 *   }
 *
 * MIT License
 */

Module.register("MMM-GuestWifi", {
	defaults: {
		// Filename of the generated QR code, relative to the module folder
		image: "guest-wifi.png",

		// Edge length of the display in pixels
		imageSize: 220,

		// Show the network name under the code. Leave empty to omit
		// it -- on a wall mirror the name reveals more than some
		// people would like.
		ssid: "",

		// Caption text under the code
		caption: "Zum Verbinden scannen"
	},

	getStyles () {
		return ["MMM-GuestWifi.css"];
	},

	start () {
		// Forces a fresh fetch whenever the PNG has been regenerated.
		// Without this the browser serves the old file from cache.
		this.cacheBuster = Date.now();
		Log.info(`${this.name} started`);
	},

	getDom () {
		const wrapper = document.createElement("div");
		wrapper.className = "guestwifi";

		const img = document.createElement("img");
		img.className = "guestwifi-code";
		img.src = `${this.file(this.config.image)}?t=${this.cacheBuster}`;
		img.width = this.config.imageSize;
		img.height = this.config.imageSize;
		img.alt = "QR-Code für das Gast-WLAN";

		// Make a missing file visible instead of showing an empty box
		// -- otherwise you end up debugging in the wrong place.
		img.onerror = () => {
			wrapper.innerHTML = "";
			const err = document.createElement("div");
			err.className = "guestwifi-error";
			err.textContent = "QR-Code fehlt — scripts/make-guest-qr.sh ausführen";
			wrapper.appendChild(err);
		};

		wrapper.appendChild(img);

		if (this.config.ssid) {
			const ssid = document.createElement("div");
			ssid.className = "guestwifi-ssid";
			ssid.textContent = this.config.ssid;
			wrapper.appendChild(ssid);
		}

		if (this.config.caption) {
			const caption = document.createElement("div");
			caption.className = "guestwifi-caption";
			caption.textContent = this.config.caption;
			wrapper.appendChild(caption);
		}

		return wrapper;
	}
});